package com.hailiang.handwrite.widget;
public class HandwriteView extends android.view.View {public boolean canDraw,imageEditable,geometry,resetTransform;public int paints;public float scale=1,tx,ty;public Runnable duringApply;public boolean isInGeometryEditMode(){return geometry;}public float getHandwriteScale(){return scale;}public float getHandwriteTranslationX(){return tx;}public float getHandwriteTranslationY(){return ty;}public void setHandwriteScale(float v,boolean b){scale=v;}public void setHandwriteTranslationX(float v,boolean b){tx=v;}public void setHandwriteTranslationY(float v,boolean b){ty=v;}public java.util.List<com.hailiang.handwrite.bean.PathInfo> paths=new java.util.ArrayList<com.hailiang.handwrite.bean.PathInfo>();public HandwriteView(android.content.Context c){super(c);}public void setCanDraw(boolean b){canDraw=b;}public void setImageEditable(boolean b){imageEditable=b;}public void setPathInfoList(java.util.List<com.hailiang.handwrite.bean.PathInfo> list,boolean b){paints++;paths=list;if(resetTransform){scale=1;tx=0;ty=0;}if(duringApply!=null)duringApply.run();}}
